import "./verifier.sol";


// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract SecureDIDRegistry {
    Verifier private verifier;

    struct DID {
        address owner;
        bool verified;
        bool revoked;
        uint256 timestamp;
    }

    mapping(address => DID) private dids;
    mapping(address => bool) private admins;
    address[] private adminList;
    mapping(address => uint256) private deposits; // Stores user deposits

    struct TransactionStats {
        uint256 total;
        uint256 success;
        uint256 failed;
    }

    mapping(address => TransactionStats) private userTransactions;
    mapping(address => bool) private activeUsers;
    address[] private allUsers;

    uint256 public totalDIDsCreated;
    uint256 public totalDIDsVerified;
    uint256 public totalDIDsRevoked;
    uint256 public totalTransactions;
    uint256 public successfulTransactions;
    uint256 public failedTransactions;

    uint256 public constant requiredDeposit = 0.01 ether;

    event DIDCreated(address indexed owner, uint256 timestamp);
    event DIDVerified(address indexed owner, uint256 timestamp);
    event DIDRevoked(address indexed owner, uint256 timestamp);
    event DepositRefunded(address indexed owner, uint256 amount);
    event AdminAdded(address indexed newAdmin);
    event AdminRemoved(address indexed removedAdmin);
    event TransactionRecorded(address indexed user, bool success);
    
    modifier onlyAdmin() {
        require(admins[msg.sender], "Unauthorized: Only admin can perform this action");
        _;
    }

    constructor(address _verifierAddress) {
    verifier = Verifier(_verifierAddress);
    admins[msg.sender] = true;
    adminList.push(msg.sender);
    }


    function createDID() public payable {
        require(dids[msg.sender].owner == address(0), "DID already exists for this address");
        require(msg.value >= requiredDeposit, "Insufficient deposit: 0.01 ETH required");

        dids[msg.sender] = DID(msg.sender, false, false, block.timestamp);
        deposits[msg.sender] = msg.value; // Store deposit amount
        allUsers.push(msg.sender);
        activeUsers[msg.sender] = true;

        userTransactions[msg.sender] = TransactionStats(0, 0, 0);
        
        totalDIDsCreated++;
        totalTransactions++;
        recordTransaction(msg.sender, true);
        emit DIDCreated(msg.sender, block.timestamp);
    }

    function verifyDID(address user) public onlyAdmin {
        require(dids[user].owner != address(0), "DID does not exist");
        require(!dids[user].verified, "DID already verified");
        require(!dids[user].revoked, "DID is revoked");

        dids[user].verified = true;
        totalDIDsVerified++;
        totalTransactions++;

        // Refund deposit upon successful verification
        if (deposits[user] > 0) {
            uint256 refundAmount = deposits[user];
            deposits[user] = 0;
            payable(user).transfer(refundAmount);
            emit DepositRefunded(user, refundAmount);
        }

        recordTransaction(user, true);
        emit DIDVerified(user, block.timestamp);
    }

    function revokeDID(address user) public onlyAdmin {
        require(dids[user].owner != address(0), "DID does not exist");
        require(!dids[user].revoked, "DID already revoked");

        dids[user].revoked = true;
        totalDIDsRevoked++;
        totalTransactions++;

        recordTransaction(user, false);
        emit DIDRevoked(user, block.timestamp);
    }

    function addNewAdmin(address newAdmin) public onlyAdmin {
        require(!admins[newAdmin], "User is already an admin");
        admins[newAdmin] = true;
        adminList.push(newAdmin);
        emit AdminAdded(newAdmin);
    }

    function removeAdmin(address admin) public onlyAdmin {
        require(admins[admin], "User is not an admin");
        require(admin != msg.sender, "Admins cannot remove themselves");

        admins[admin] = false;

        for (uint256 i = 0; i < adminList.length; i++) {
            if (adminList[i] == admin) {
                adminList[i] = adminList[adminList.length - 1];
                adminList.pop();
                break;
            }
        }

        emit AdminRemoved(admin);
    }

    function isDIDVerified(address user) public view returns (bool) {
        require(dids[user].owner != address(0), "DID does not exist");
        return dids[user].verified && !dids[user].revoked;
    }

    function getDIDStatus(address user) public view returns (string memory) {
        require(dids[user].owner != address(0), "DID does not exist");

        if (dids[user].revoked) {
            return "Revoked";
        } else if (dids[user].verified) {
            return "Verified";
        } else {
            return "Unverified";
        }
    }

    function isAdmin(address user) public view returns (bool) {
        return admins[user];
    }

    function recordTransaction(address user, bool success) internal {
        userTransactions[user].total++;
        if (success) {
            userTransactions[user].success++;
            successfulTransactions++;
        } else {
            userTransactions[user].failed++;
            failedTransactions++;
        }
        activeUsers[user] = true;
        emit TransactionRecorded(user, success);
    }

    function getGlobalStats() public view returns (uint256, uint256, uint256, uint256, uint256, uint256) {
        return (totalDIDsCreated, totalDIDsVerified, totalDIDsRevoked, totalTransactions, successfulTransactions, failedTransactions);
    }

    receive() external payable {}

    function verifyDIDWithZKP(
    address user,
    uint[2] memory a,
    uint[2][2] memory b,
    uint[2] memory c,
    uint[2] memory input
) public onlyAdmin {
    require(dids[user].owner != address(0), "DID does not exist");
    require(!dids[user].verified, "DID already verified");
    require(!dids[user].revoked, "DID is revoked");

    Verifier.Proof memory proof = Verifier.Proof({
        a: Pairing.G1Point(a[0], a[1]),
        b: Pairing.G2Point([b[0][0], b[0][1]], [b[1][0], b[1][1]]),
        c: Pairing.G1Point(c[0], c[1])
    });

    require(verifier.verifyTx(proof, input), "Invalid ZKP proof");

    dids[user].verified = true;
    totalDIDsVerified++;
    totalTransactions++;

    if (deposits[user] > 0) {
        uint256 refundAmount = deposits[user];
        deposits[user] = 0;
        payable(user).transfer(refundAmount);
        emit DepositRefunded(user, refundAmount);
    }

    recordTransaction(user, true);
    emit DIDVerified(user, block.timestamp);
}





}
